         * The end as painted, "" where none is.
         */
        val ident: String,
        @SerialName("headwind_kt")
        val headwindKt: Double,
        @SerialName("crosswind_kt")
        val crosswindKt: Double,
        @SerialName("gust_crosswind_kt")
        val gustCrosswindKt: Double? = null,
        val calm: Boolean,
        /**
         * A variable wind's speed, there only for one.
         */
        @SerialName("variable_kt")
        val variableKt: Double? = null,
        /**
         * There only where calm picked the runway in use.
         */
        @SerialName("in_use")
        val inUse: String? = null,
        /**
         * Where the wind was reported when not at the field.
         */
        val from: EngineContract.WindPickAnswerFrom? = null,
        @SerialName("forecast_at")
        val forecastAt: Double? = null,
    )

    /**
     * Where the wind was reported when not at the field.
     */
    @Serializable
    data class WindPickAnswerFrom(
        val ident: String,
        val nm: Double,
    )

    @Serializable
    data class WindPickInput(
        val runways: List<EngineContract.Runway>? = null,
        /**
         * The nearest report's wind, for a field that reports none (a TAF's, with forecast_at).
         */
        val nearby: EngineContract.WindPickInputNearby? = null,
        /**
         * Seconds since 1970.
         */
        @SerialName("forecast_at")
        val forecastAt: Double? = null,
    )

    /**
     * The nearest report's wind, for a field that reports none (a TAF's, with forecast_at).
     */
    @Serializable
    data class WindPickInputNearby(
        val station: String? = null,
        @SerialName("distance_nm")
        val distanceNm: Double? = null,
        @SerialName("dir_true_deg")
        val dirTrueDeg: Double? = null,
        @SerialName("speed_kt")
        val speedKt: Double? = null,
        @SerialName("gust_kt")
        val gustKt: Double? = null,
    )

    @Serializable
    data class WindSteadyOrGustInput(
        @SerialName("steady_kt")
        val steadyKt: Double,
        @SerialName("gust_kt")
        val gustKt: Double? = null,
    )

    @Serializable
    data class WindTriangleAnswer(
        val wca: Double,
        val th: Double,
        val gs: Double,
    )

    @Serializable
    data class WindTriangleInput(
        val tc: Double,
        val tas: Double,
        @SerialName("wind_from_deg")
        val windFromDeg: Double,
        @SerialName("wind_kt")
        val windKt: Double,
    )

    @Serializable
    data class WordingLatLon(
        val lat: Double,
        val lon: Double,
    )

    /**
     * A VOR as the planner sends one; with no mag_var it gives no radials.
     */
    @Serializable
    data class WordingStation(
        val ident: String? = null,
        val lat: Double,
        val lon: Double,
        /**
         * The station's magnetic variation, degrees east.
         */
        @SerialName("mag_var")
        val magVar: Double? = null,
    )

    @Serializable
    data class WordsAltFtInput(
        val ft: Double? = null,
    )

    @Serializable
    data class WordsCeilingAndVisibilityInput(
        @SerialName("ceiling_ft")
        val ceilingFt: Double? = null,
        @SerialName("visibility_sm")
        val visibilitySm: Double? = null,
    )

    @Serializable
    data class WordsFlightLevelInput(
        val ft: Double? = null,
    )

    @Serializable
    data class WordsGroupedInput(
        val n: Double,
    )

    @Serializable
    data class WordsNumInput(
        val n: Double? = null,
    )

    @Serializable
    data class WordsOneInput(
        val n: Double,
    )

    @Serializable
    data class WordsToFixedInput(
        val n: Double,
        /**
         * 0 to 20; 1 where missing.
         */
        val digits: Double? = null,
    )

    @Serializable
    data class WorkingsRightInput(
        val key: String,
        val typed: Double,
        val answer: Double,
    )

    /**
     * A SIGMET, AIRMET or G-AIRMET in one reading (AIM 7-1-6).
     */
    @Serializable
    data class WorseAdvisory(
        /**
         * What names the advisory from one reading to the next: its text as sent, or its hazard, severity and altitudes.
         */
        val key: String,
        /**
         * "SIGMET", "Convective SIGMET", "AIRMET" or "G-AIRMET", as the app words it.
         */
        val kind: String,
        /**
         * Its hazard as sent ("IFR", "TURB", "ICE").
         */
        val hazard: String? = null,
        /**
         * Whether the briefing places it on the route.
         */
        @SerialName("on_route")
        val onRoute: Boolean? = null,
    )

    /**
     * A field's ceiling and visibility in one reading: its METAR's, or its TAF's for the flight's time there. The engine reads the flight category (AIM 7-1-7).
     */
    @Serializable
    data class WorseField(
        val ident: String,
        @SerialName("ceiling_ft")
        val ceilingFt: Double? = null,
        @SerialName("visibility_sm")
        val visibilitySm: Double? = null,
        /**
         * The lowest broken, overcast or obscured layer sent with no height (14 CFR 1.1): not known, not none.
         */
        @SerialName("ceiling_unknown")
        val ceilingUnknown: Boolean? = null,
        /**
         * A TAF where the flight lands (a stop or the destination): only those are compared.
         */
        val arrival: Boolean? = null,
    )
}
